class Order:
    def __init__(self, unit_pence, qty):
        self.unit_pence, self.qty = unit_pence, qty

    @property
    def total_pence(self):
        return self.unit_pence * self.qty

print(Order(1050, 3).total_pence)

class Item:
    @property
    def qty(self):
        return self._qty

    @qty.setter
    def qty(self, value):
        if value < 0:
            raise ValueError('qty must be >= 0')
        self._qty = value

i = Item()
i.qty = 5
print(i.qty)

